<?php $heading='Rekapitulasi Lamaran';$kicker='LAPORAN · REKRUTMEN';$subtitle='Ringkasan lowongan dan perkembangan seleksi berdasarkan data tersimpan.';$headingAction='<a class="button secondary" href="'.e(url('rekapitulasi/ekspor')).'">'.icon('download').' Ekspor CSV</a>';require ROOT.'/app/Views/components/heading.php';?>
