<section class="card"><h2>Rekap Per Mahasiswa</h2><div class="table-scroll"><table><thead><tr><th>Mahasiswa</th><th>Program Studi</th><th>Lowongan</th><th>Perusahaan</th><th>Status</th><th>Detail</th></tr></thead><tbody><?php foreach($mahasiswa as $a):?><tr><td><strong><?= e($a['namaMahasiswa']) ?></strong><small><?= e($a['NIM']) ?></small></td><td><?= e($a['jurusan']) ?></td><td><?= e($a['namaLowongan']) ?></td><td><?= e($a['namaPerusahaan']) ?></td><td><?= badge($a['statusLamaran']) ?></td><td><a href="<?= e(url($currentUser['role']==='Admin'?'lamaran/detail':'seleksi/detail',['id'=>$a['idLamaran']])) ?>">Lihat →</a></td></tr><?php endforeach;?></tbody></table></div></section>
